import React, { useState, useEffect } from 'react';

const Watchlist = ({ onSelectStock }) => {
    const [watchlist, setWatchlist] = useState([]);
    const [loading, setLoading] = useState(true);
    const [newSymbol, setNewSymbol] = useState('');

    useEffect(() => {
        fetchWatchlist();
    }, []);

    const fetchWatchlist = async () => {
        try {
            const response = await fetch('http://localhost:5000/api/watchlist', {
                credentials: 'include'
            });
            const data = await response.json();
            setWatchlist(data);
            setLoading(false);
        } catch (error) {
            console.error('Error fetching watchlist:', error);
            setLoading(false);
        }
    };

    const addToWatchlist = async () => {
        if (!newSymbol) return;
        try {
            const response = await fetch('http://localhost:5000/api/watchlist/add', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ symbol: newSymbol })
            });
            const data = await response.json();
            if (data.message) {
                setNewSymbol('');
                fetchWatchlist();
            } else {
                alert(data.error || 'Failed to add');
            }
        } catch (error) {
            console.error('Error adding to watchlist:', error);
        }
    };

    const removeFromWatchlist = async (symbol) => {
        try {
            const response = await fetch('http://localhost:5000/api/watchlist/remove', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ symbol })
            });
            const data = await response.json();
            if (data.message) {
                fetchWatchlist();
            }
        } catch (error) {
            console.error('Error removing from watchlist:', error);
        }
    };

    if (loading) {
        return <div style={{ padding: '10px', color: '#8a9bb5' }}>Loading watchlist...</div>;
    }

    return (
        <div style={{
            background: '#141b2b',
            padding: '15px',
            borderRadius: '10px',
            border: '1px solid #2a3a5c'
        }}>
            <h3 style={{ marginBottom: '15px', color: '#e0e6ed' }}>⭐ Watchlist</h3>
            
            <div style={{ display: 'flex', gap: '10px', marginBottom: '15px' }}>
                <input
                    type="text"
                    placeholder="Add symbol (e.g., RELIANCE)"
                    value={newSymbol}
                    onChange={(e) => setNewSymbol(e.target.value.toUpperCase())}
                    style={{
                        flex: 1,
                        padding: '8px 12px',
                        background: '#1a2332',
                        border: '1px solid #2a3a5c',
                        borderRadius: '6px',
                        color: 'white',
                        outline: 'none'
                    }}
                />
                <button
                    onClick={addToWatchlist}
                    style={{
                        padding: '8px 16px',
                        background: '#4CAF50',
                        color: 'white',
                        border: 'none',
                        borderRadius: '6px',
                        cursor: 'pointer'
                    }}
                >
                    Add
                </button>
            </div>

            {watchlist.length === 0 ? (
                <p style={{ color: '#8a9bb5', textAlign: 'center' }}>No stocks in watchlist</p>
            ) : (
                <div>
                    {watchlist.map((item) => (
                        <div
                            key={item.symbol}
                            onClick={() => onSelectStock(item.symbol)}
                            style={{
                                display: 'flex',
                                justifyContent: 'space-between',
                                alignItems: 'center',
                                padding: '10px 12px',
                                borderBottom: '1px solid #2a3a5c',
                                cursor: 'pointer'
                            }}
                            onMouseEnter={(e) => e.target.style.background = '#1a2332'}
                            onMouseLeave={(e) => e.target.style.background = 'transparent'}
                        >
                            <div>
                                <div style={{ fontWeight: 'bold' }}>{item.symbol}</div>
                                <div style={{ fontSize: '12px', color: '#8a9bb5' }}>{item.name}</div>
                            </div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                                <span style={{ fontWeight: 'bold' }}>
                                    ₹{item.price ? item.price.toFixed(2) : 'N/A'}
                                </span>
                                <button
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        removeFromWatchlist(item.symbol);
                                    }}
                                    style={{
                                        background: 'none',
                                        border: 'none',
                                        color: '#dc3545',
                                        cursor: 'pointer',
                                        fontSize: '16px',
                                        padding: '0 4px'
                                    }}
                                >
                                    ✕
                                </button>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};

export default Watchlist;
